update group_buy_order_list
set status = #{status} , update_time = now()
where order_id = #{orderId} and user_id = #{userId} and status = #{preStatus}

update group_buy_order_list
set status = #{status} , update_time = now() , out_trade_time = #{outTradeTime}
where order_id = #{orderId} and user_id = #{userId} and status = #{preStatus}

mapper.select:
select  id,user_id,team_id,order_id,activity_id,start_time,
end_time,goods_id,source,channel,original_price,
deduction_price,pay_price,status,out_trade_no,create_time,update_time
,biz_id
from group_buy_order_list


        and id = #{id}


        and user_id = #{userId}


        and team_id = #{teamId}


        and order_id = #{orderId}


        and activity_id = #{activityId}


        and goods_id = #{goodsId}


        and source = #{source}


        and channel = #{channel}


        and status = #{status}


        and out_trade_no = #{outTradeNo}


        and biz_id = #{bizId}


order by id desc

select id,user_id,team_id,order_id,activity_id,start_time,
       end_time,goods_id,source,channel,original_price,
       deduction_price,pay_price,status,out_trade_no,create_time,update_time,biz_id
from group_buy_order_list
where user_id = #{userId}
  and activity_id = #{activityId}
  and goods_id = #{goodsId}
  and source = #{source}
  and channel = #{channel}
  and status in (0, 1)
  and end_time > now()
order by id desc
limit 1

